    ('Facelift'::text, 'SUV 5-door'::text, 4208::integer, 1794::integer, 1508::integer, 145::integer, 1280::integer, 405::integer, 1050::integer, 1840::integer, 560::integer, 50::numeric, 5::integer)
),
phase_lookup as (
  select cp.id, cp.phase_label
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'Audi' and cm.name = 'Q2' and cp.generation_code = 'GA'
